import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
// import { stringify } from 'querystring';

// import { downloadJSON } from '../../NJSCoreLib';
import { RGBToHex, COLOR_SPACE } from '../NJSCoreLib/ColorUtility';
import { getGridHelper } from '../NJSCoreLib/ThreeHelper';

export class ThreeSimple {
	canvas: HTMLCanvasElement;
	host: HTMLElement;
	ctx: CanvasRenderingContext2D;
	t: number = 0.0;

	renderer: THREE.WebGLRenderer;
	camera: THREE.PerspectiveCamera;
	scene: THREE.Scene;
	sceneRayCast: any = [];

	controls: OrbitControls;
	raycaster: THREE.Raycaster;

	active = false;

	mouse = new THREE.Vector2(0, 0);

	INTERSECTED: any = undefined;

	// dataJson: any;

	v: number[] = [0, 0, 0];

	constructor(div: HTMLElement, title = 'Title') {
		this.host = div;

		const divTop = document.createElement('div');
		this.host.append(divTop);
		divTop.style.position = 'absolute';

		const divTitle = document.createElement('div');
		divTitle.textContent = title;
		divTop.append(divTitle);

		const divDownload = document.createElement('div');
		divDownload.textContent = 'download';
		divTop.append(divDownload);
		// divDownload.onclick = () => {
		//     const stringData = JSON.stringify(this.dataJson);
		//     // console.log(stringData)
		//     downloadJSON(stringData, 'download.json');
		// };

		this.initCanvas();
	}
	public initCanvas() {
		this.scene = new THREE.Scene();
		this.scene.background = new THREE.Color(200, 200, 200);
		this.scene.castShadow = true;

		this.scene.background = new THREE.Color(0xefefef);

		this.camera = new THREE.PerspectiveCamera(30, this.host.clientWidth / this.host.clientHeight, 1, 5000);
		this.camera.position.set(0, 0, 250);

		// const ambientLight = new THREE.AmbientLight(0xcccccc, 0.4);
		// ambientLight.castShadow = true;
		// this.scene.add(ambientLight);

		// var pointLight = new THREE.PointLight(0xffffff, 0.8);
		// pointLight.castShadow = true;
		// this.scene.add(pointLight);

		this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
		this.renderer.setPixelRatio(this.host.clientWidth / this.host.clientHeight);
		this.renderer.domElement.id = 'ThreeSandbox';
		this.renderer.setSize(this.host.clientWidth, this.host.clientHeight);
		this.host.appendChild(this.renderer.domElement);

		this.controls = new OrbitControls(this.camera, this.renderer.domElement);
		this.controls.enablePan = true; // .screenSpacePanning = true;
		this.controls.enableDamping = true;
		this.controls.enableZoom = true;
		this.controls.rotateSpeed = 0.2;
		this.controls.zoomSpeed = 2;
		this.controls.update();

		this.raycaster = new THREE.Raycaster();

		this.init();
	}
	public init() {
		this.eventBind();
		this.loop();

		this.scene.add(getGridHelper(50, 10));
		this.active = true;
	}
	public eventBind() {
		this.renderer.domElement.onmousemove = (e: MouseEvent) => this.mouseMove(e);
		this.renderer.domElement.onmousedown = (e: MouseEvent) => this.mouseDown(e);
		this.renderer.domElement.onmouseup = (e: MouseEvent) => this.mouseUp(e);
	}
	public mouseDown(e: MouseEvent) {
		// console.log(e);
		if (this.INTERSECTED) {
			console.log(this.INTERSECTED.data);
			// const ss = stringify(this.INTERSECTED.data).split('&'); // .replace('&', '/br');
			// this.app.divPanel.innerHTML = '';
			// for (let s of ss) {
			//     this.app.divPanel.innerHTML += s + '<br>' ;
			// }
		} else {
			// this.app.divPanel.innerHTML = '';
		}
	}
	public mouseUp(e: MouseEvent) {
		// console.log(e);
	}
	public mouseMove(e: MouseEvent) {
		this.mouse.x = (e.offsetX / this.host.clientWidth) * 2 - 1;
		this.mouse.y = -(e.offsetY / this.host.clientHeight) * 2 + 1;
	}
	public loop() {
		requestAnimationFrame(() => {
			this.loop();
		});

		if (!this.active) {
			return;
		}

		this.controls.update();
		this.raycaster.setFromCamera(this.mouse, this.camera);

		const intersects = this.raycaster.intersectObjects(this.sceneRayCast);

		if (intersects.length > 0) {
			if (this.INTERSECTED !== intersects[0].object) {
				if (this.INTERSECTED) {
					this.INTERSECTED.material.emissive.setHex(this.INTERSECTED.currentHex);
				}
				this.INTERSECTED = intersects[0].object;
				this.INTERSECTED.currentHex = this.INTERSECTED.material.emissive.getHex();
				this.INTERSECTED.material.emissive.setHex(0xff0000);

				this.INTERSECTED.scale.x = 1.1;
				this.INTERSECTED.scale.y = 1.1;
				this.INTERSECTED.scale.z = 1.1;
				console.log(this.INTERSECTED);
			}
		} else {
			if (this.INTERSECTED) {
				this.INTERSECTED.material.emissive.setHex(this.INTERSECTED.currentHex);

				this.INTERSECTED.scale.x = 1;
				this.INTERSECTED.scale.y = 1;
				this.INTERSECTED.scale.z = 1;
			}

			this.INTERSECTED = undefined;
		}

		this.renderer.render(this.scene, this.camera);

		this.render();
		this.t += 0.01;
	}
	public render() {
		console.log('render loop');
	}
	public initVis(dataVis: any, colors: number[][], space: COLOR_SPACE) {
		const geometry = new THREE.SphereGeometry(0.5, 10, 10);

		for (let i = 0; i < dataVis.length; i++) {
			const data: any = dataVis[i];

			const colHex = RGBToHex(colors[i][0], colors[i][1], colors[i][2]);
			const mat = new THREE.MeshLambertMaterial({ color: colHex });
			mat.emissive = new THREE.Color(colHex);
			const object = new THREE.Mesh(geometry, mat);

			object.position.x = data[0];
			object.position.y = data[1];
			object.position.z = data[2];

			// object.rotation.x = Math.random() * 2 * Math.PI;
			// object.rotation.y = Math.random() * 2 * Math.PI;
			// object.rotation.z = Math.random() * 2 * Math.PI;

			object.scale.x = 1; //dataJson.radius;
			object.scale.y = 1; //dataJson.radius;
			object.scale.z = 1; //dataJson.radius;

			object['data'] = data;

			this.scene.add(object);
			this.sceneRayCast.push(object);
		}

		// switch (space) {
		//     case COLOR_SPACE.LAB:
		//         this.app.threeCore.scene.add(getGridLegend(-0, 0, -100, 100, 50, 10));
		//         break;
		//     case COLOR_SPACE.HSV:
		//         this.app.threeCore.scene.add(getGridLegend(-0, -0, -0, 360, 100, 100));
		//         break;
		//     default:
		//         this.app.threeCore.scene.add(getGridLegend(-0, -0, -0, 255, 255, 255));
		//         break;
		// }
	}
}
